class Cart {
  final List<Item> items;
  Cart(this.items);

  // derived: cannot drift out of sync with items
  double get subtotal => items.fold(0.0, (sum, i) => sum + i.price);
  bool get isEmpty => items.isEmpty;

  // pure and expensive, and the object is immutable: pay once
  late final List<Item> byPrice =
      [...items]..sort((a, b) => a.price.compareTo(b.price));
}

class Temperature {
  double _celsius = 0;

  double get celsius => _celsius;
  set celsius(double value) {
    if (value < -273.15) throw ArgumentError('below absolute zero');
    _celsius = value; // a setter is where validation belongs
  }

  // a read/write pair in another unit, stored nowhere
  double get fahrenheit => _celsius * 9 / 5 + 32;
  set fahrenheit(double f) => celsius = (f - 32) * 5 / 9;
}

