enum OrderStatus implements Comparable<OrderStatus> {
  pending('pending', 'Waiting for payment', retryable: true),
  paid('paid', 'Paid', retryable: false),
  cancelled('canceled', 'Cancelled', retryable: false); // API spells it with one l

  const OrderStatus(this.apiValue, this.label, {required this.retryable});

  final String apiValue;
  final String label;
  final bool retryable;

  bool get isFinal => this == paid || this == cancelled;

  // a factory is allowed as long as it returns one of the values
  factory OrderStatus.fromApi(String raw) => values.firstWhere(
        (s) => s.apiValue == raw,
        orElse: () => throw FormatException('unknown status: $raw'),
      );

  @override
  int compareTo(OrderStatus other) => index.compareTo(other.index);
}

