class Tag {
  final String name;
  final int weight;
  const Tag(this.name, this.weight);

  // ❌ == alone: the Set buckets by the identity hash, so duplicates survive
  @override
  bool operator ==(Object other) =>
      other is Tag && other.name == name && other.weight == weight;
}

void main() {
  final s = {const Tag('dart', 1), const Tag('dart', 1)};
  print(s.length); // 2 — equal, but hashed into different buckets
}

class GoodTag {
  final String name;
  final List<String> aliases;
  const GoodTag(this.name, this.aliases);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is GoodTag &&
          other.runtimeType == runtimeType &&
          other.name == name &&
          listEquals(other.aliases, aliases);

  @override
  int get hashCode => Object.hash(name, Object.hashAll(aliases));
}

// The mutation trap — same shape, but with a non-final field
class MutableKey {
  String name;
  MutableKey(this.name);
  @override
  bool operator ==(Object o) => o is MutableKey && o.name == name;
  @override
  int get hashCode => name.hashCode;
}

