  Future<String> fetch(String id) async => 'from network: $id';
}

mixin Caching on Base {
  final _cache = <String, String>{};

  @override
  Future<String> fetch(String id) async {
    print('caching');
    return _cache[id] ??= await super.fetch(id); // super => Base
  }
}

mixin Logging on Base {
  @override
  Future<String> fetch(String id) async {
    print('logging');
    final result = await super.fetch(id); // super => whatever is to my left
    print('got $result');
    return result;
  }
}

class Repo extends Base with Caching, Logging {}
// chain: Base -> Base+Caching -> Base+Caching+Logging -> Repo
// prints: logging, caching  — every call is logged, hit or miss

class OtherRepo extends Base with Logging, Caching {}
// prints: caching, then logging ONLY on a miss — a different feature entirely

// ❌ a mixin that forgets super silently disables everything to its left
mixin BrokenLogging on Base {
  @override
  Future<String> fetch(String id) async {
    print('logging');
    return 'stub'; // Caching and Base never run
  }
}

abstract class Repo {
  Repo() {
    onInit(); // ❌ virtual call from a constructor body
  }
  void onInit();
}

class UserRepo extends Repo {
  final int retries;      // set during step 1 — safe
  late final String _url; // assigned in the body — step 3, too late

  UserRepo(this.retries) {
    _url = 'https://api.example.com/users';
  }

  @override
  void onInit() => print('$_url x $retries');
  // LateInitializationError: Field '_url' has not been initialized.
}

// ✅ the constructor only assigns; initialization is a separate phase
class SafeRepo {
  final int retries;
  late final String _url;

  SafeRepo._(this.retries);

  static SafeRepo create(int retries) {
    final repo = SafeRepo._(retries);
    repo.onInit(); // fully built before anything overridable runs
    return repo;
  }

  void onInit() {
    _url = 'https://api.example.com/users';
  }
}

// Flutter's version of the same rule
class _CounterState extends State<Counter> with SingleTickerProviderStateMixin {
  late final Ticker _ticker;

  @override
  void initState() {
    super.initState(); // widget and context are attached only now
    _ticker = createTicker(_tick);
  }
}
